    public void salvar() {
        Leitor p = new Leitor();
        p.setCodleitor(Integer.parseInt(campo1.getText()));
        p.setNome(campo2.getText().toUpperCase());
        p.setEndereco(campo3.getText().toUpperCase());
        p.setTelefone(campo4.getText().toUpperCase());
        p.setSituacao(campo5.getText().toUpperCase());

        try {
            dao.salvar(p);
            JOptionPane.showMessageDialog(null, "LEITOR SALVO COM SUCESSO");
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, e, "ERRO", JOptionPane.ERROR_MESSAGE);
        }
        limpar();
    }

    public void consultar() {
        int chave = Integer.parseInt(campo1.getText());
        Object obj1 = new Object();
        try {
            obj1 = dao.consultar("Leitor.findByCodleitor", "codleitor", chave);
            Leitor p = (Leitor) obj1;
            campo2.setText(p.getNome());
            campo3.setText(p.getEndereco());
            campo3.setCaretPosition(0);
            campo4.setText(p.getTelefone());
            campo5.setText(p.getSituacao());
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "LEITOR NÃO EXISTE", "ERRO", 0);
        }
    }

    public void excluir() {
        int chave = Integer.parseInt(campo1.getText());
        try {
            dao.excluir("Leitor.findByCodleitor", "codleitor", chave);
            JOptionPane.showMessageDialog(null, "LEITOR EXCLUIDO COM SUCESSO");
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "LEITOR NÃO EXISTE", "ERRO", 0);
        }
        limpar();
    }

    public void limpar() {
        campo1.setText("");
        campo2.setText("");
        campo3.setText("");
        campo4.setText("");
        campo5.setText("");
    }

    public void sair() {
        dispose();
    }
